export function Notifications() {
  const { issues, unread, setUnread } = useCivic();
  const navigate = useNavigate();
  const [tab, setTab] = useState("Unread");
  const notes = issues.slice(0, tab === "Unread" ? Math.max(unread, 1) : issues.length);
  return <div className="page narrow enter"><PageHead eyebrow="Inbox" title="Notifications" description="Assignment, workflow, and SLA updates." actions={<Button variant="secondary" onClick={() => setUnread(0)}><Check size={17} />Mark all as read</Button>} /><div className="tabs"><button className={tab === "Unread" ? "active" : ""} onClick={() => setTab("Unread")}>Unread <span>{unread}</span></button><button className={tab === "All" ? "active" : ""} onClick={() => setTab("All")}>All</button></div><Card className="notification-list">{notes.length ? notes.map((issue, i) => <button key={issue.id} onClick={() => { setUnread(Math.max(0, unread - 1)); navigate(`/issues/${issue.id}`); }}><span className={`notification-icon ${i === 0 ? "urgent" : ""}`}>{i === 0 ? <AlertTriangle size={19} /> : <Bell size={19} />}</span><p><strong>{i === 0 ? `SLA risk: ${issue.title}` : `${issue.status}: ${issue.title}`}</strong><span>{issue.id} · {issue.department} · {formatAge(issue.updated)}</span></p>{i < unread && <i className="unread-dot" />}<ChevronRight size={18} /></button>) : <Empty title="You’re all caught up" text="New assignments and workflow updates will appear here." />}</Card></div>;
}

export function Sla() {
  const { issues } = useCivic();
  const now = new Date("2026-03-24T12:00:00");
  const tracked = issues.filter(i => i.status !== "Closed").sort((a, b) => +new Date(a.sla) - +new Date(b.sla));
  return <div className="page enter"><PageHead eyebrow="Service commitments" title="SLA & Escalations" description="Deadlines are calculated from report timestamps and service rules." actions={<Button variant="secondary"><FileDown size={17} />Export view</Button>} /><div className="sla-summary"><Card><AlertTriangle /><span><b>{tracked.filter(i => new Date(i.sla) < now).length}</b><small>Overdue</small></span></Card><Card><Clock3 /><span><b>{tracked.filter(i => new Date(i.sla) >= now).length}</b><small>Approaching</small></span></Card><Card><ShieldCheck /><span><b>86%</b><small>Within SLA</small></span></Card></div><Card className="table-card"><div className="sla-list">{tracked.map(issue => { const hours = Math.round((+new Date(issue.sla) - +now) / 36e5); return <Link key={issue.id} to={`/issues/${issue.id}`}><span className={`sla-state ${hours < 0 ? "overdue" : hours < 24 ? "warning" : ""}`}><Clock3 size={18} /></span><p><strong>{issue.title}</strong><small>{issue.id} · {issue.department}</small></p><span><small>Deadline</small><strong>{new Date(issue.sla).toLocaleDateString([], { month: "short", day: "numeric" })}</strong></span><Badge tone={hours < 0 ? "danger" : hours < 24 ? "warning" : "success"}>{hours < 0 ? `${Math.abs(hours)}h overdue` : `${hours}h remaining`}</Badge><span>Level {issue.escalation}</span><ChevronRight size={18} /></Link>; })}</div></Card></div>;
}

