export function Reports() {
  const { issues } = useCivic();
  const [category, setCategory] = useState("All");
  const [busy, setBusy] = useState("");
  const filtered = category === "All" ? issues : issues.filter(i => i.category === category);
  const csv = () => { setBusy("Preparing CSV…"); window.setTimeout(() => { downloadCsv(filtered, `civicfix-issues-2026-02-24-to-2026-03-24`); setBusy("CSV downloaded successfully"); }, 500); };
  return <div className="page enter"><PageHead eyebrow="Reporting center" title="Reports & Exports" description="Generate real exports from the current fictional demonstration records." /><div className="reports-layout"><Card className="report-builder"><Title level={2}>Build a report</Title><div className="form-grid"><label>From<Input type="date" defaultValue="2026-02-24" /></label><label>To<Input type="date" defaultValue="2026-03-24" /></label><label>Department<Select><option>All departments</option><option>Public Works</option><option>Sanitation</option></Select></label><label>Category<Select value={category} onChange={e => setCategory(e.target.value)}><option>All</option><option>Roads</option><option>Sanitation</option><option>Streetlights</option><option>Water</option><option>Other</option></Select></label></div><div className="demo-callout"><Sparkles size={20} /><p><strong>Demonstration report</strong><span>Exports are marked as fictional and contain the filtered records shown in this preview.</span></p></div><div className="export-actions"><Button onClick={csv}><Download size={17} />Export CSV</Button><Button variant="secondary" onClick={() => { setBusy("Opening print dialog…"); setTimeout(() => window.print(), 300); }}><Printer size={17} />Print / Save PDF</Button></div>{busy && <p className="success-message" role="status"><CheckCircle2 size={17} />{busy}</p>}</Card><Card className="report-preview"><div className="card-head"><div><span className="eyebrow">Preview</span><Title level={2}>Alder Bay issue report</Title></div><Badge tone="success">Demonstration</Badge></div><div className="preview-metrics"><span><b>{filtered.length}</b><small>Records</small></span><span><b>{filtered.filter(i => openStatuses.includes(i.status)).length}</b><small>Open</small></span><span><b>{filtered.filter(i => i.status === "Closed").length}</b><small>Closed</small></span></div><div className="preview-rows">{filtered.slice(0, 5).map(i => <div key={i.id}><span>{i.id}</span><strong>{i.title}</strong><Badge tone={toneFor(i.status)}>{i.status}</Badge></div>)}</div><small>Showing up to 5 preview records. The CSV contains all {filtered.length} filtered records.</small></Card></div><Card><div className="card-head"><Title level={2}>Download history</Title><Badge>Stored for this session</Badge></div><Empty title="No saved export history" text="Generated files download directly to your device in demonstration mode." /></Card></div>;
}

