export function Profile() {
  const { profile, setProfile } = useCivic();
  const [draft, setDraft] = useState(profile);
  const [saved, setSaved] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const changePhoto = (e: ChangeEvent<HTMLInputElement>) => { const file = e.target.files?.[0]; if (!file) return; if (!["image/jpeg", "image/png", "image/webp"].includes(file.type) || file.size > 5 * 1024 * 1024) { alert("Choose a JPEG, PNG, or WebP image smaller than 5 MB."); return; } const reader = new FileReader(); reader.onload = () => setDraft({ ...draft, photo: String(reader.result) }); reader.readAsDataURL(file); };
  const dirty = JSON.stringify(draft) !== JSON.stringify(profile);
  return <div className="page narrow enter"><PageHead eyebrow="Administrator account" title="Profile" description="Manage how you appear to other CivicFix administrators." actions={<Link className="button secondary" to="/profile/security"><KeyRound size={17} />Security</Link>} /><Card className="profile-hero"><div className="avatar large">{draft.photo ? <img src={draft.photo} alt="" /> : "AM"}<button aria-label="Change profile photo" onClick={() => fileRef.current?.click()}><Camera size={17} /></button></div><div><Title level={2}>{draft.name}</Title><p>{draft.email}</p><Badge tone="success">{draft.role}</Badge></div><input ref={fileRef} type="file" hidden accept="image/jpeg,image/png,image/webp" onChange={changePhoto} /></Card><Card className="profile-form"><div className="card-head"><div><Title level={2}>Account information</Title><p>Keep your administrator details current.</p></div>{dirty && <Badge tone="warning">Unsaved changes</Badge>}</div><div className="form-grid"><label>Full name<Input value={draft.name} onChange={e => { setDraft({ ...draft, name: e.target.value }); setSaved(false); }} /></label><label>Email address<Input type="email" value={draft.email} onChange={e => setDraft({ ...draft, email: e.target.value })} /></label><label>Role<Input value={draft.role} disabled /></label><label>Service area<Input value="Alder Bay" disabled /></label></div><div className="photo-guidance"><Camera size={20} /><p><strong>Profile photo</strong><span>JPEG, PNG, or WebP. Maximum 5 MB. In demonstration mode, the preview is stored only for this session.</span></p>{draft.photo && <Button variant="ghost" onClick={() => setDraft({ ...draft, photo: "" })}>Remove</Button>}</div><div className="form-actions"><Button variant="secondary" disabled={!dirty} onClick={() => setDraft(profile)}>Cancel changes</Button><Button disabled={!dirty || !draft.name.trim()} onClick={() => { setProfile(draft); setSaved(true); }}>Save changes</Button></div>{saved && <p className="success-message"><CheckCircle2 size={17} />Profile changes saved for this demonstration session.</p>}</Card></div>;
}

export function Security() {
  const [show, setShow] = useState(false);
  const [values, setValues] = useState({ current: "", next: "", confirm: "" });
  const checks = { length: values.next.length >= 10, upper: /[A-Z]/.test(values.next), number: /\d/.test(values.next), match: values.next.length > 0 && values.next === values.confirm };
  return <div className="page narrow enter"><button className="back-link" onClick={() => history.back()}><ArrowLeft size={17} />Back to profile</button><PageHead eyebrow="Account protection" title="Password & Security" description="Connected authentication is not configured for this demonstration." /><Card className="security-card"><div className="demo-callout"><LockKeyhole size={21} /><p><strong>Validation-only demonstration</strong><span>This form demonstrates password requirements but will not change a real password. Values are never stored.</span></p></div><label>Current password<span className="password-wrap"><Input type={show ? "text" : "password"} value={values.current} onChange={e => setValues({ ...values, current: e.target.value })} /><Button variant="ghost" onClick={() => setShow(!show)}>{show ? <EyeOff size={18} /> : <Eye size={18} />}</Button></span></label><label>New password<Input type={show ? "text" : "password"} value={values.next} onChange={e => setValues({ ...values, next: e.target.value })} /></label><label>Confirm new password<Input type={show ? "text" : "password"} value={values.confirm} onChange={e => setValues({ ...values, confirm: e.target.value })} /></label><div className="strength"><span><i className={values.next.length > 3 ? "ok" : ""} /><i className={values.next.length > 7 ? "ok" : ""} /><i className={Object.values(checks).every(Boolean) ? "ok" : ""} /></span><small>{values.next ? (Object.values(checks).every(Boolean) ? "Strong" : "Keep going") : "Enter a new password"}</small></div><div className="requirements">{[["length", "At least 10 characters"], ["upper", "One uppercase letter"], ["number", "One number"], ["match", "Passwords match"]].map(([key, label]) => <span className={checks[key as keyof typeof checks] ? "met" : ""} key={key}><Check size={15} />{label}</span>)}</div><Button disabled={!values.current || !Object.values(checks).every(Boolean)} onClick={() => alert("Validation passed. No password was changed because no authentication provider is connected.")}>Validate password change</Button></Card></div>;
}

