function downloadCsv(issues: Issue[], name: string) {
  const safe = (value: unknown) => { let text = String(value ?? ""); if (/^[=+\-@]/.test(text)) text = `'${text}`; return `"${text.replaceAll('"', '""')}"`; };
  const rows = [["ID", "Title", "Category", "Severity", "Status", "Neighborhood", "Department", "Priority", "SLA"], ...issues.map(i => [i.id, i.title, i.category, i.severity, i.status, i.neighborhood, i.department, i.priority, i.sla])];
  const blob = new Blob([`# CivicFix demonstration report — fictional Alder Bay data\n${rows.map(row => row.map(safe).join(",")).join("\n")}`], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${name}.csv`; anchor.click(); URL.revokeObjectURL(url);
}
function formatAge(date: string) {
  const days = Math.max(0, Math.round((+new Date("2026-03-24T12:00:00") - +new Date(date)) / 864e5));
  return days === 0 ? "Today" : `${days}d ago`;
}
